// [MEDIUM_PRIORITY] CODE_QUALITY: Class structure reviewed
// [MEDIUM_PRIORITY] VALIDATION: String conversion safety
// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.connectivity.notificationimport android.app.Notificationimport android.app.RemoteInputimport android.content.Intentimport android.os.Bundleimport android.service.notification.NotificationListenerServiceimport android.service.notification.StatusBarNotificationimport androidx.core.app.NotificationCompatimport timber.log.Timberimport java.util.LinkedHashMap/** * NOUS — Nous Notification Listener Service (Module 11 v3 — P0). * * Real Android [NotificationListenerService] that receives notifications * from WhatsApp / Telegram / Signal / SMS and feeds them into the * [com.roshan.persona.connectivity.unified.MessagingUnificationEngine]. * * ## What it does * *  - **onNotificationPosted(sbn)** — extract `packageName`, `title`, *    `text`, `category`, `postTime` and cache the notification in *    [NotificationCache] (in-memory LRU 100). *  - **onNotificationRemoved(sbn)** — drop the entry from the cache. *  - **dismissNotification(key)** — call `cancelNotification(key)` *    to dismiss the system notification. *  - **replyToNotification(key, reply)** — find the notification's *    reply action (the one with a [RemoteInput]), put the reply text *    into the RemoteInput results bundle, and call `action.actionIntent.send()`. * * @see <a href="docs/strategy/module-11-connectivity-strategy-v3.md">§MessagingUnificationEngine</a> */class NousNotificationListenerService : NotificationListenerService() {    override fun onListenerConnected() {        super.onListenerConnected()        Timber.tag(TAG).i("Notification listener connected — ready to receive notifications.")        instance = this    }    override fun onListenerDisconnected() {        super.onListenerDisconnected()        Timber.tag(TAG).w("Notification listener disconnected.")        instance = null    }    override fun onNotificationPosted(sbn: StatusBarNotification?) {        sbn ?: return        try {            val notification = sbn.notification ?: return            val packageName = sbn.packageName ?: return            val extras = notification.extras ?: return            val title = extras.getCharSequence(Notification.EXTRA_TITLE)?.toString().orEmpty()            val text = extras.getCharSequence(Notification.EXTRA_TEXT)?.toString().orEmpty()            val bigText = extras.getCharSequence(Notification.EXTRA_BIG_TEXT)?.toString()            val category = notification.category            val postTime = sbn.postTime            val sender = extractSender(notification, extras)            val entry = CachedNotification(                key = sbn.key,                packageName = packageName,                title = title,                text = bigText ?: text,                sender = sender,                category = category,                postTime = postTime,                notification = notification,            )            cache.put(sbn.key, entry)            Timber.tag(TAG).d("Posted: pkg=%s sender=%s title=%s textLen=%d",                packageName, sender, title, entry.text.length)        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "onNotificationPosted failed for pkg=%s", sbn.packageName)        }    }    override fun onNotificationRemoved(sbn: StatusBarNotification?) {        sbn ?: return        try {            cache.remove(sbn.key)        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "onNotificationRemoved failed")        }    }    /**     * Extract the sender's display name from a MessagingStyle notification.     *     * WhatsApp/Telegram use `Notification.MessagingStyle` so each message has     * a `Person` associated with it. We pull the most-recent message's sender.     */    private fun extractSender(notification: Notification, extras: Bundle): String? {        return try {            // Use NotificationCompat.MessagingStyle.extractMessagingStyleFromNotification            // (static) which reconstructs the MessagingStyle object from the            // notification extras bundle. Then call getMessages() to get the            // list of MessagingStyle.Message, each carrying a Person + sender.            val style = NotificationCompat.MessagingStyle                .extractMessagingStyleFromNotification(notification) ?: return null            val messages = style.messages            if (messages.isNullOrEmpty()) return null            val last = messages.last()            // Message.getPerson() returns Person on API 28+; getSender() returns            // CharSequence which works on all API levels.            last.person?.name?.toString() ?: last.sender?.toString()        } catch (t: Throwable) {            Timber.tag(TAG).e(t, "extractSender failed")            null        }    }    companion object {        private const val TAG = "NousNotifListener"        private const val CACHE_CAPACITY = 100        @Volatile        private var instance: NousNotificationListenerService? = null        private val cache: NotificationCache = NotificationCache(CACHE_CAPACITY)        /** Get the cache (always non-null — same instance across the app lifetime). */        fun getCache(): NotificationCache = cache        /** True if the listener is currently connected. */        fun isConnected(): Boolean = instance != null        /**         * Dismiss a system notification by its key. Returns true if the         * cancelNotification call succeeded.         */        fun dismissNotification(key: String): Boolean {            val svc = instance ?: return false            return try {                svc.cancelNotification(key)                true            } catch (t: Throwable) {                Timber.tag(TAG).e(t, "dismissNotification failed for key=%s", key)                false            }        }        /**         * Reply to a notification via its RemoteInput reply action.         *         * Strategy §"MessagingUnificationEngine" — v3 supports replying to         * WhatsApp/Telegram notifications directly from the unified inbox.         */        fun replyToNotification(key: String, reply: String): Boolean {            val entry = cache.get(key) ?: run {                Timber.tag(TAG).w("replyToNotification: no cached entry for key=%s", key)                return false            }            val actions = entry.notification.actions ?: run {                Timber.tag(TAG).w("replyToNotification: no actions for key=%s", key)                return false            }            val replyAction = actions.firstOrNull { action ->                action.remoteInputs?.any { it != null } == true            } ?: run {                Timber.tag(TAG).w("replyToNotification: no RemoteInput action for key=%s", key)                return false            }            return try {                val remoteInputs = replyAction.remoteInputs?.filterNotNull().orEmpty()                val resultsIntent = Intent()                val resultsBundle = Bundle()                for (ri in remoteInputs) {                    resultsBundle.putCharSequence(ri.resultKey, reply)                }                RemoteInput.addResultsToIntent(remoteInputs.toTypedArray(), resultsIntent, resultsBundle)                // PendingIntent.send(Context, code, Intent) variant — passes our results intent.                replyAction.actionIntent?.send(null, 0, resultsIntent)                Timber.tag(TAG).i("Reply sent to notification key=%s: %s", key, reply.take(50))                true            } catch (t: Throwable) {                Timber.tag(TAG).e(t, "replyToNotification send failed for key=%s", key)                false            }        }    }}/** * In-memory LRU cache for parsed notifications (Strategy §"MessagingUnificationEngine" * — "in-memory LRU 100"). Keyed by [StatusBarNotification.getKey]. * * Uses [LinkedHashMap] with access-order eviction. */class NotificationCache(private val capacity: Int) {    private val map: LinkedHashMap<String, CachedNotification> = object : LinkedHashMap<String, CachedNotification>(        capacity, 0.75f, true,    ) {        override fun removeEldestEntry(eldest: Map.Entry<String, CachedNotification>?): Boolean {            return size > capacity        }    }    @Synchronized    fun put(key: String, entry: CachedNotification) {        map[key] = entry    }    @Synchronized    operator fun get(key: String): CachedNotification? = map[key]    @Synchronized    fun remove(key: String): CachedNotification? = map.remove(key)    @Synchronized    fun all(): List<CachedNotification> = map.values.toList()    @Synchronized    fun size(): Int = map.size    @Synchronized    fun clear() {        map.clear()    }}/** * Parsed notification entry (kept in [NotificationCache]). * * The raw [Notification] is retained so replyToNotification can access * `notification.actions` + `remoteInputs` — these are not serializable. */data class CachedNotification(    val key: String,    val packageName: String,    val title: String,    val text: String,    val sender: String?,    val category: String?,    val postTime: Long,    val notification: Notification,)/** * True if our [NousNotificationListenerService] singleton is currently connected. */fun isNotificationListenerConnected(): Boolean = try {    NousNotificationListenerService.isConnected()} catch (t: Throwable) {    false}